import 'package:flutter/material.dart';import 'package:shared_preferences/shared_preferences.dart';import 'api_client.dart';
class AuthProvider extends ChangeNotifier{final ApiClient api;AuthProvider(this.api);bool loading=false;String? token;String? name;String? role;bool get loggedIn=>token!=null;Future<void>restore()async{final p=await SharedPreferences.getInstance();token=p.getString('token');name=p.getString('name');role=p.getString('role');notifyListeners();}Future<bool>login(String email,String password)async{loading=true;notifyListeners();try{final d=await api.post('/auth/login',data:{'email':email,'password':password});token=d['token'];name=d['fullName'];role=d['role'];final p=await SharedPreferences.getInstance();await p.setString('token',token!);await p.setString('name',name!);await p.setString('role',role!);return true;}catch(_){return false;}finally{loading=false;notifyListeners();}}Future<bool>register(String first,String last,String email,String password,String phone)async{try{final d=await api.post('/auth/register',data:{'firstName':first,'lastName':last,'email':email,'password':password,'phone':phone});token=d['token'];name=d['fullName'];role=d['role'];final p=await SharedPreferences.getInstance();await p.setString('token',token!);await p.setString('name',name!);await p.setString('role',role!);notifyListeners();return true;}catch(_){return false;}}Future<void>logout()async{final p=await SharedPreferences.getInstance();await p.clear();token=null;name=null;role=null;notifyListeners();}}
